// Dense reference caches are initialized directly from analytic coordinates;
// they are never unpacked from the candidate's packed carrier or commit outputs.
__global__ void fillDense(float* key,float* value,int chunk,int layer,Spans spans,size_t words){
    for(size_t i=size_t(blockIdx.x)*blockDim.x+threadIdx.x;i<words;i+=size_t(gridDim.x)*blockDim.x){
        size_t u=i;const int d=u%256;u/=256;const int p=u%4096;u/=4096;const int h=u%4,b=u/4;
        key[i]=__uint_as_float(uint32_t(cacheBits(b,0,h,p,d,layer,chunk,spans,false))<<16);
        value[i]=__uint_as_float(uint32_t(cacheBits(b,1,h,p,d,layer,chunk,spans,false))<<16);
    }
}
__global__ void verifyDense(const float* key,const float* value,int chunk,int layer,Spans spans,bool updated,size_t words,unsigned long long* errors){
    for(size_t i=size_t(blockIdx.x)*blockDim.x+threadIdx.x;i<words;i+=size_t(gridDim.x)*blockDim.x){
        size_t u=i;const int d=u%256;u/=256;const int p=u%4096;u/=4096;const int h=u%4,b=u/4;
        for(int which=0;which<2;++which){
            uint16_t expected=cacheBits(b,which,h,p,d,layer,chunk,spans,false);
            if(updated&&p>=spans.start[b]&&p<spans.start[b]+spans.count[b]){
                const int t=p-spans.start[b];expected=bf16(currentBits(((b*chunk+t)*4+h)*256+d,which!=0));
            }
            if(__float_as_uint(which?value[i]:key[i])!=(uint32_t(expected)<<16))atomicAdd(errors,1ull);
        }
    }
}
void denseExact(const float* key,const float* value,int chunk,int layer,Spans spans,bool updated,size_t words,Device& errors,cudaStream_t s){
    check(cudaMemsetAsync(errors.p,0,8,s));verifyDense<<<4096,256,0,s>>>(key,value,chunk,layer,spans,updated,words,(unsigned long long*)errors.p);
    check(cudaGetLastError());unsigned long long count=0;check(cudaMemcpyAsync(&count,errors.p,8,cudaMemcpyDeviceToHost,s));check(cudaStreamSynchronize(s));
    require(count==0,updated?"Reference full FP32 cache differs from BF16-rounded oracle":"Readonly dense reference cache changed");
}
